                || string.IsNullOrWhiteSpace(definition.DisplayName)
                || string.IsNullOrWhiteSpace(definition.Owner.OwnerId))
                throw new ArgumentException("invalid-role-definition", nameof(definitions));
            if (!snapshot.TryAdd(definition.Role, definition))
                throw new ArgumentException("duplicate-role-reference", nameof(definitions));
