public static class RoleGateResolver
{
    public static bool Allows(RoleGate gate, RoleVocabulary vocabulary, HeldRoleSet heldRoles)
    {
        ArgumentNullException.ThrowIfNull(gate);
        ArgumentNullException.ThrowIfNull(vocabulary);
        ArgumentNullException.ThrowIfNull(heldRoles);
        if (gate.RequiredRoles.Count == 0) return true;
        try
        {
            if (gate.RequiredRoles.Any(role => vocabulary.Resolve(role) is null)) return false;
        }
        catch (ArgumentException)
        {
            return false;
        }
        var held = heldRoles.Roles.ToHashSet();
        return gate.RequiredRoles.Any(held.Contains);
    }
}
